begin;
select plan(12);
select ok(not has_table_privilege('authenticated','stream_push_devices','select'),'device ownership/recovery metadata is private');
select ok(not has_function_privilege('authenticated','reserve_stream_push_device(uuid,text,text,boolean)','execute'),'only authenticated server can reserve a device');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
create temp table push_fixture as select reserve_stream_push_device('00000000-0000-4000-8000-00000000000a','stream-device-fixture-opaque-token','register',false) as value;
select is((select value->>'status' from push_fixture),'reserved','first operation is reserved');
select is(reserve_stream_push_device('00000000-0000-4000-8000-00000000000b','stream-device-fixture-opaque-token','register',true)->>'status','in_flight','another account cannot race a live device lease');
select ok(not finish_stream_push_device('00000000-0000-4000-8000-00000000000a','stream-device-fixture-opaque-token',gen_random_uuid(),true),'stale lease cannot publish device ownership');
select ok(finish_stream_push_device('00000000-0000-4000-8000-00000000000a','stream-device-fixture-opaque-token',(select (value->>'leaseToken')::uuid from push_fixture),true),'accepted private provider commits');
select is((select previews_enabled from push_device_tokens where token='stream-device-fixture-opaque-token'),false,'private per-device preference persists');
select is(reserve_stream_push_device('00000000-0000-4000-8000-00000000000b','stream-device-fixture-opaque-token','unregister',true)->>'status','not_owned','old/different account cannot remove another owner device');
create temp table transferred as select reserve_stream_push_device('00000000-0000-4000-8000-00000000000b','stream-device-fixture-opaque-token','register',true) as value;
select ok((select value->'previousOwners' from transferred) @> '["00000000-0000-4000-8000-00000000000a"]'::jsonb,'new account removes the previous vendor recipient first');
select ok(finish_stream_push_device('00000000-0000-4000-8000-00000000000b','stream-device-fixture-opaque-token',(select (value->>'leaseToken')::uuid from transferred),false),'provider failure settles lease without publishing new token');
select is((select user_id::text from push_device_tokens where token='stream-device-fixture-opaque-token'),'00000000-0000-4000-8000-00000000000a','failed provider switch cannot claim successful registration');
select ok((select previous_owners from stream_push_devices where token_hash=encode(extensions.digest('stream-device-fixture-opaque-token','sha256'),'hex')) @> array['00000000-0000-4000-8000-00000000000a']::uuid[],'failed switch preserves recovery identity');
reset role;
select * from finish();
rollback;
